package org.apache.commons.lang3;

import java.io.*;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import java.util.regex.Pattern;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for StringUtils.join(Object[] array, char separator, int startIndex, int endIndex)
 */
public class StringUtils_join_TriageGen0Test {

    @Test
    public void testJoin_NullArray() {
        // if (array == null) { return null; }
        assertNull("Should return null when array is null", 
            StringUtils.join(null, ',', 0, 0));
    }

    @Test
    public void testJoin_NoOfItemsLessThanOrEqualToZero() {
        // if (noOfItems <= 0) { return EMPTY; }
        Object[] array = {"a", "b", "c"};

        // Case: endIndex == startIndex
        assertEquals("", StringUtils.join(array, ',', 1, 1));

        // Case: endIndex < startIndex
        assertEquals("", StringUtils.join(array, ',', 2, 1));
    }

    @Test
    public void testJoin_SingleElement() {
        // Test single element range (startIndex to endIndex where endIndex = startIndex + 1)
        Object[] array = {"A", "B", "C"};
        assertEquals("A", StringUtils.join(array, ',', 0, 1));
        assertEquals("B", StringUtils.join(array, ',', 1, 2));
    }

    @Test
    public void testJoin_MultipleElements() {
        // Standard case: multiple elements with separator
        Object[] array = {"A", "B", "C", "D"};
        assertEquals("A,B,C", StringUtils.join(array, ',', 0, 3));
        assertEquals("B,C,D", StringUtils.join(array, ',', 1, 4));
    }

    @Test
    public void testJoin_WithNullElements() {
        // if (array[i] != null) { buf.append(array[i]); }
        // Test that null elements are skipped but separators are still appended
        Object[] array = {"A", null, "C", null, "E"};
        // Range 0 to 5: "A" + "," + (skip null) + "," + "C" + "," + (skip null) + "," + "E"
        // Wait, looking at logic: 
        // i=0: append A
        // i=1: i > 0, append separator, array[1] is null, nothing appended.
        // i=2: i > 0, append separator, append C
        // i=3: i > 0, append separator, array[3] is null, nothing appended.
        // i=4: i > 0, append separator, append E
        // Result: "A,,C,,E"
        assertEquals("A,,C,,E", StringUtils.join(array, ',', 0, 5));
    }

    @Test
    public void testJoin_DifferentSeparator() {
        Object[] array = {"1", "2", "3"};
        assertEquals("1|2|3", StringUtils.join(array, '|', 0, 3));
        assertEquals("1-2-3", StringUtils.join(array, '-', 0, 3));
    }

    @Test
    public void testJoin_NonStringObjects() {
        // Test that it handles non-string objects via implicit toString()
        Object[] array = {1, 2.5, true};
        assertEquals("1,2.5,true", StringUtils.join(array, ',', 0, 3));
    }

    @Test
    public void testJoin_LargeIndexRange() {
        // Test boundary logic for startIndex and endIndex
        Object[] array = {"a", "b"};
        // endIndex is exclusive
        assertEquals("a,b", StringUtils.join(array, ',', 0, 2));
    }
}
